package com.comandos.reservation.service;import com.comandos.reservation.model.ReservationStatusType;import jakarta.persistence.EntityManager;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ReservationReferenceData implements ApplicationRunner{private final EntityManager em;public ReservationReferenceData(EntityManager em){this.em=em;}@Override@Transactional public void run(ApplicationArguments args){add("ACTIVE","Active reservation",false,10);add("CANCELLED","Cancelled",true,20);add("EXPIRED","Expired",true,30);}private void add(String code,String name,boolean terminal,int order){if(em.createQuery("select count(s) from ReservationStatusType s where s.code=:c",Long.class).setParameter("c",code).getSingleResult()>0)return;var s=new ReservationStatusType();s.code=code;s.name=name;s.active=true;s.terminal=terminal;s.displayOrder=order;s.systemProtected=true;em.persist(s);}}
